const KEY_OVERRIDES = {
    "PayDateOnBD": "Pay Date on Business Day",
    "Accrual": "Leave",
    "AccrualId": "Leave Id",
    "AccrualName": "Leave Name",
    "AccrualCode": "Leave Code",
    "AccrualRate": "Leave Rate",
    "AccrualRateUnit": "Leave Rate Unit",
    "AccrualCycleDay": "Leave Cycle Day",
    "AccrualCycleMonth": "Leave Cycle Month"
};

if (KEY_OVERRIDES[key]) return KEY_OVERRIDES[key];

return key
    // 1. Insert space between lowercase and uppercase
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    // 2. Insert space after an acronym (e.g., SSSDeduction -> SSS Deduction)
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
    // Capitalize the first letter
    .replace(/^./, str => str.toUpperCase())
    .trim();

if (!entity) return [];
if (!config) config = {};

const list = [];
const excludeKeys = [...this.GLOBAL_EXCLUSIONS, ...(config.exclude || [])];

// Define the metadata keys that should be pushed to the bottom
const metaKeys = [
    'CreatedDate', 'CreatedBy',
    'UpdatedDate', 'UpdatedBy',
    'DeletedDate', 'DeletedBy'
];

let keys = Object.keys(entity);

// SORTING LOGIC: 
// 1. Non-meta keys first (alphabetical, putting 'Tax' before 'TaxId')
// 2. Meta keys last (in the exact order defined above)
keys.sort((a, b) => {
    const indexA = metaKeys.indexOf(a);
    const indexB = metaKeys.indexOf(b);
    const isMetaA = indexA !== -1;
    const isMetaB = indexB !== -1;

    if (isMetaA && !isMetaB) return 1;
    if (!isMetaA && isMetaB) return -1;
    if (isMetaA && isMetaB) return indexA - indexB;

    return a.localeCompare(b);
});

let metaStarted = false;

keys.forEach(key => {
    if (excludeKeys.includes(key)) return;

    let value = entity[key];
    if (value === undefined || value === null || value === "") return;

    // --- INSERT SPACER BEFORE METADATA ---
    const isMeta = metaKeys.includes(key);
    if (isMeta && !metaStarted) {
        metaStarted = true;
        if (list.length > 0) {
            list.push({
                key: "", // Renders blank label
                originalKey: "__spacer__",
                value: "", // Renders blank value
                isSpacer: true // Optional flag for UI logic (e.g., ng-class)
            });
        }
    }

    let displayValue = value;

    // 1. Explicit Mappers
    if (config.mappers && config.mappers[key]) {
        displayValue = config.mappers[key](value);
    }
    // 2. Boolean Logic
    else if (
        typeof value === "boolean" ||
        ((value === 0 || value === 1) && (key.match(/^(Is|Has|Need|Can|Active|Deleted)/)))
    ) {
        displayValue = value ? 'YES' : 'NO';
    }
    // 3. Date Logic
    else if ((key.includes("Date") || key.endsWith("At")) && !key.includes("Rate") && key !== "PayDateOnBD") {
        const parsed = this.utils.parseDate(value);
        displayValue = parsed ?? new Date(value).toLocaleDateString();
    }

    // 4. Handle Special YTD Object with value & value2 ---
    if (typeof displayValue === "object" && displayValue !== null && 'value' in displayValue) {
        list.push({
            key: this._formatLabel(key),
            originalKey: key,
            value: displayValue.value,
            value2: displayValue.value2
        });
        return; // Skip standard push
    }

    // Standard push for flat values
    list.push({
        key: this._formatLabel(key),
        originalKey: key,
        value: displayValue
    });
});

return list;

if (isAdding || (isEditing && currentId !== newId)) {
    return await utilsService.handleUnsavedChanges(true);
}

return true;
